[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<!-- ===================== STYLES ===================== -->
<style>
* { box-sizing: border-box; margin: 0; padding: 0; }

body, table, td, th {
    font-family: Arial, sans-serif;
    font-size: 11px;
    color: #000;
}

.invoice-wrapper {
    width: 100%;
    max-width: 900px;
    margin: 0 auto;
}

.invoice-title {
    text-align: center;
    font-size: 13px;
    font-weight: bold;
    margin-bottom: 4px;
}

/* ---- HEADER TABLE ---- */
.header-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
}
.header-table td, .header-table th {
    border: 1px solid #000;
    padding: 4px 6px;
    vertical-align: top;
}
.header-table .no-border-top { border-top: none; }

/* ---- ITEMS TABLE ---- */
.invoice-table {
    width: 100%;
    border-collapse: collapse;
    border: 1px solid #000;
    border-top: none;
}
.invoice-table th {
    border: 1px solid #000;
    text-align: center;
    font-size: 11px;
    padding: 3px 4px;
    background: #fff;
}
.invoice-table td {
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-top: none;
    border-bottom: none;
    padding: 2px 4px;
    vertical-align: top;
    font-size: 11px;
}
.invoice-table tbody tr:last-child td {
    border-bottom: 1px solid #000;
}

/* ---- AMOUNT IN WORDS ---- */
.amtwords-table {
    width: 100%;
    border: 1px solid #000;
    border-top: none;
    border-collapse: collapse;
    font-size: 11px;
    margin-top: -1px;
}
.amtwords-table td { padding: 5px 6px; }

/* ---- HSN SUMMARY ---- */
.hsn-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    border: 1px solid #000;
    border-top: none;
    margin-top: -1px;
}
.hsn-table th, .hsn-table td {
    border: 1px solid #000;
    padding: 3px 5px;
    text-align: center;
}

/* ---- TAX AMOUNT IN WORDS ---- */
.taxwords-table {
    width: 100%;
    border: 1px solid #000;
    border-top: none;
    border-collapse: collapse;
    font-size: 11px;
    margin-top: -1px;
}
.taxwords-table td { padding: 5px 6px; }

/* ---- FOOTER / BANK / DECLARATION ---- */
.footer-table {
    width: 100%;
    border: 1px solid #000;
    border-top: none;
    border-collapse: collapse;
    font-size: 11px;
    margin-top: -1px;
}
.footer-table td {
    border: 1px solid #000;
    padding: 5px 6px;
    vertical-align: top;
}

/* ---- SIGNATURE ROW ---- */
.sig-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
}
.sig-table td {
    border-top: 1px solid #000;
    border-right: 1px solid #000;
    height: 55px;
    padding: 4px 6px;
    vertical-align: bottom;
    width: 33.33%;
}
.sig-table td:last-child { border-right: none; }

/* ---- MISC ---- */
.text-left   { text-align: left; }
.text-center { text-align: center; }
.text-right  { text-align: right; }
.bold        { font-weight: bold; }
.computer-gen {
    text-align: center;
    font-size: 10px;
    padding: 4px 0 2px;
}
</style>

<!-- ===================== DISCOUNT FLAG ===================== -->
{% set show_discount = namespace(val=false) %}
{% for item in doc.items %}
    {% set disc = item.discount_on_price_list_rate or item.discount_percentage or 0 %}
    {% if disc > 0 %}{% set show_discount.val = true %}{% endif %}
{% endfor %}

<!-- ===================== INVOICE TITLE ===================== -->
<div class="invoice-title">Tax Invoice</div>

<!-- ===================== HEADER ===================== -->
<table class="header-table">
<tr>
    <!-- LEFT: Company info -->
    <td style="width:60%; vertical-align:top;">
        <b>{{ frappe.db.get_value("Bank Account", {"company": doc.company}, "parent_company") or doc.company }}</b><br>
        {{ doc.company_address_display or "" }}
    </td>
    <!-- RIGHT: Invoice details (rowspan=2) -->
    <td rowspan="2" style="width:40%; padding:0; vertical-align:top;">
        <table style="width:100%; border-collapse:collapse;">
            <tr>
                <td style="border:1px solid #000; padding:4px; width:50%;">
                    Invoice No.<br><b>{{ doc.name }}</b>
                </td>
                <td style="border:1px solid #000; padding:4px; width:50%;">
                    Dated<br><b>{{ doc.posting_date }}</b>
                </td>
            </tr>
            <tr>
                <td style="border:1px solid #000; padding:4px;">
                    Mode/Terms of Payment<br>
                    {{ doc.payment_terms_template or "" }}
                </td>
                <td style="border:1px solid #000; padding:4px;">&nbsp;</td>
            </tr>
            <tr>
                <td style="border:1px solid #000; padding:4px;">
                    Reference No. &amp; Date
                </td>
                <td style="border:1px solid #000; padding:4px;">
                    Other References
                </td>
            </tr>
            <tr>
                <td style="border:1px solid #000; padding:4px;">
                    Buyer's Order No.
                </td>
                <td style="border:1px solid #000; padding:4px;">
                    Dated
                </td>
            </tr>
            <tr>
                <td style="border:1px solid #000; padding:4px;">
                    Dispatch Doc No.<br>{{ doc.dispatch_doc_no or "" }}
                </td>
                <td style="border:1px solid #000; padding:4px;">
                    Delivery Note Date<br>{{ doc.delivery_note_date or "" }}
                </td>
            </tr>
            <tr>
                <td style="border:1px solid #000; padding:4px;">
                    Dispatched through<br>{{ doc.shipping_rule or "" }}
                </td>
                <td style="border:1px solid #000; padding:4px;">
                    Destination<br>{{ doc.shipping_address_name or "" }}
                </td>
            </tr>
            <tr>
                <td colspan="2" style="border:1px solid #000; padding:4px;">
                    Terms of Delivery<br><br><br><br>
                </td>
            </tr>
        </table>
    </td>
</tr>
<tr>
    <!-- LEFT: Buyer info -->
    <td style="vertical-align:top;">
        <b>Buyer (Bill to)</b><br>
        <b>{{ doc.customer_name }}</b><br>
        {% if doc.customer_address %}
            {{ frappe.db.get_value("Address", doc.customer_address, "address_line1") or "" }}<br>
            {% set addr2 = frappe.db.get_value("Address", doc.customer_address, "address_line2") %}
            {% if addr2 %}{{ addr2 }}<br>{% endif %}
            {{ frappe.db.get_value("Address", doc.customer_address, "city") or "" }}
            {{ frappe.db.get_value("Address", doc.customer_address, "state") or "" }}<br>
            {{ frappe.db.get_value("Address", doc.customer_address, "pincode") or "" }}<br>
            {{ frappe.db.get_value("Address", doc.customer_address, "country") or "" }}<br>
        {% endif %}
        {% if doc.contact_person %}
            Phone: {{ frappe.db.get_value("Contact", doc.contact_person, "mobile_no") or "" }}<br>
        {% elif doc.contact_mobile %}
            Phone: {{ doc.contact_mobile }}<br>
        {% endif %}
        {% if doc.contact_email %}
            E-Mail: {{ doc.contact_email }}
        {% endif %}
        <br>
        {% set cust_gstin = frappe.db.get_value("Customer", doc.customer, "gstin") or
                            frappe.db.get_value("Address", doc.customer_address, "gstin") or "" %}
        {% if cust_gstin %}GSTIN: {{ cust_gstin }}<br>{% endif %}
        {% set cust_state_code = frappe.db.get_value("Address", doc.customer_address, "gst_state_number") or "" %}
        {% if cust_state_code %}State Name: &nbsp; State Code: {{ cust_state_code }}{% endif %}
    </td>
</tr>
</table>

<!-- ===================== ITEMS TABLE ===================== -->
<table class="invoice-table">
<thead>
<tr>
    <th style="width:3%">Sl<br>No</th>
    <th style="width:34%">Description of Goods</th>
    <th style="width:9%">HSN/SAC</th>
    <th style="width:5%">GST</th>
    <th style="width:9%">Quantity</th>
    <th style="width:10%">Rate<br>(Incl. of Tax)</th>
    <th style="width:9%">Rate</th>
    <th style="width:5%">per</th>
    {% if show_discount.val %}
    <th style="width:5%">Disc.&nbsp;%</th>
    {% endif %}
    <th style="width:11%">Amount</th>
</tr>
</thead>
<tbody>

{% for item in doc.items %}
<tr>
    <td class="text-center">{{ loop.index }}</td>

    <td>
        <b>{{ item.item_name }}{% if item.item_code and item.item_code != item.item_name %}_{{ item.item_code }}{% endif %}</b>
        {% if item.description and item.description != item.item_name %}
            <br><span style="font-size:10px;">{{ item.description }}</span>
        {% endif %}
    </td>

    <td class="text-center">{{ item.gst_hsn_code or item.hsn_code or "" }}</td>

    <td class="text-center">
        {% set gst = namespace(val=0) %}
        {% if item.item_tax_rate %}
            {% if "2.5" in item.item_tax_rate %}{% set gst.val = 5 %}
            {% elif "6" in item.item_tax_rate %}{% set gst.val = 12 %}
            {% elif "9" in item.item_tax_rate %}{% set gst.val = 18 %}
            {% elif "14" in item.item_tax_rate %}{% set gst.val = 28 %}
            {% elif "0" in item.item_tax_rate %}{% set gst.val = 0 %}
            {% endif %}
        {% endif %}
        {{ gst.val }}&nbsp;%
    </td>

    <td class="text-center bold">{{ item.qty }}&nbsp;{{ item.uom }}</td>

    <!-- Rate incl. tax -->
    <td class="text-right">
        {% set gst2 = namespace(val=0) %}
        {% if item.item_tax_rate %}
            {% if "2.5" in item.item_tax_rate %}{% set gst2.val = 5 %}
            {% elif "6" in item.item_tax_rate %}{% set gst2.val = 12 %}
            {% elif "9" in item.item_tax_rate %}{% set gst2.val = 18 %}
            {% elif "14" in item.item_tax_rate %}{% set gst2.val = 28 %}
            {% elif "0" in item.item_tax_rate %}{% set gst2.val = 0 %}
            {% endif %}
        {% endif %}
        {% if item.price_list_rate %}
            {{ "%.2f"|format(item.price_list_rate * (1 + gst2.val / 100)) }}
        {% else %}
            {{ "%.2f"|format(item.rate * (1 + gst2.val / 100)) }}
        {% endif %}
    </td>

    <!-- Base Rate -->
    <td class="text-right">
        {% if item.price_list_rate %}
            {{ "%.2f"|format(item.price_list_rate) }}
        {% else %}
            {{ "%.2f"|format(item.rate) }}
        {% endif %}
    </td>

    <td class="text-center">{{ item.uom }}</td>

    {% if show_discount.val %}
    <td class="text-center">
        {% set disc = item.discount_on_price_list_rate or item.discount_percentage or 0 %}
        {{ "%.0f"|format(disc) }}&nbsp;%
    </td>
    {% endif %}

    <td class="text-right bold">{{ "%.2f"|format(item.net_amount) }}</td>
</tr>
{% endfor %}

<!-- ---- SUB-TOTAL ROW ---- -->
<tr>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    <td style="border-top:1px solid #000;"></td>
    {% if show_discount.val %}<td style="border-top:1px solid #000;"></td>{% endif %}
    <td class="text-right" style="border-top:1px solid #000;">{{ "%.2f"|format(doc.net_total) }}</td>
</tr>

<!-- ---- TAXES ROWS ---- -->
<tr>
    <td></td>
    <td class="text-right" style="border-left:none;">
        {% for tax in doc.taxes %}
            <b>{{ tax.description }} @ {{ "%.2f"|format(tax.rate) }}%</b><br>
        {% endfor %}
        <b>Roundoff</b>
    </td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    <td></td>
    {% if show_discount.val %}<td></td>{% endif %}
    <td class="text-right">
        {% for tax in doc.taxes %}
            <b>{{ "%.2f"|format(tax.tax_amount) }}</b><br>
        {% endfor %}
        <b>({{ "+" if doc.rounding_adjustment >= 0 else "-" }}){{ "%.2f"|format(doc.rounding_adjustment|abs) }}</b>
    </td>
</tr>

<!-- ---- GRAND TOTAL ROW ---- -->
<tr style="border-top:1px solid #000;">
    <td></td>
    <td class="text-right bold">Total</td>
    <td></td>
    <td></td>
    <td class="text-center bold">
        <!-- Sum of qty with UOM -->
        {% set total_qty = namespace(val=0) %}
        {% for item in doc.items %}{% set total_qty.val = total_qty.val + item.qty %}{% endfor %}
        {{ "%.0f"|format(total_qty.val) }}&nbsp;No's
    </td>
    <td></td>
    <td></td>
    <td></td>
    {% if show_discount.val %}<td></td>{% endif %}
    <td class="text-right bold" style="border-top:1px solid #000;">
        ₹&nbsp;{{ "%.2f"|format(doc.grand_total) }}
    </td>
</tr>

</tbody>
</table>

<!-- ===================== AMOUNT IN WORDS ===================== -->
<table class="amtwords-table">
<tr>
    <td style="width:70%; border-right:1px solid #000; padding:5px 6px;">
        <span style="font-size:10px;">Amount Chargeable (in words)</span><br>
        <b>{{ frappe.utils.money_in_words(doc.grand_total, doc.currency) }}</b>
    </td>
    <td style="width:30%; text-align:right; padding:5px 6px; vertical-align:bottom;">
        <b>E. &amp; O.E</b>
    </td>
</tr>
</table>

<!-- ===================== HSN SUMMARY ===================== -->
{% set hsn_map = namespace(data={}) %}
{% for item in doc.items %}
    {% set hsn = item.gst_hsn_code or item.hsn_code or "NA" %}
    {% set gst = namespace(val=0) %}
    {% if item.item_tax_rate %}
        {% if "2.5" in item.item_tax_rate %}{% set gst.val = 5 %}
        {% elif "6" in item.item_tax_rate %}{% set gst.val = 12 %}
        {% elif "9" in item.item_tax_rate %}{% set gst.val = 18 %}
        {% elif "14" in item.item_tax_rate %}{% set gst.val = 28 %}
        {% elif "0" in item.item_tax_rate %}{% set gst.val = 0 %}
        {% endif %}
    {% endif %}
    {% set key = hsn ~ "_" ~ gst.val %}
    {% if key not in hsn_map.data %}
        {% set _ = hsn_map.data.update({key: {"hsn": hsn, "gst": gst.val, "taxable": 0}}) %}
    {% endif %}
    {% set row = hsn_map.data[key] %}
    {% set _ = row.update({"taxable": row.taxable + item.net_amount}) %}
{% endfor %}

<table class="hsn-table">
<thead>
<tr>
    <th rowspan="2" style="border:1px solid #000;">HSN/SAC</th>
    <th rowspan="2" style="border:1px solid #000;">Taxable Value</th>
    <th colspan="2" style="border:1px solid #000;">CGST</th>
    <th colspan="2" style="border:1px solid #000;">SGST/UTGST</th>
    <th rowspan="2" style="border:1px solid #000;">Total Tax Amount</th>
</tr>
<tr>
    <th style="border:1px solid #000;">Rate</th>
    <th style="border:1px solid #000;">Amount</th>
    <th style="border:1px solid #000;">Rate</th>
    <th style="border:1px solid #000;">Amount</th>
</tr>
</thead>
<tbody>
{% set total_taxable = namespace(val=0) %}
{% set total_tax     = namespace(val=0) %}
{% for key, row in hsn_map.data.items() %}
    {% set cgst_rate = row.gst / 2 %}
    {% set sgst_rate = row.gst / 2 %}
    {% set cgst_amt  = row.taxable * cgst_rate / 100 %}
    {% set sgst_amt  = row.taxable * sgst_rate / 100 %}
    {% set total     = cgst_amt + sgst_amt %}
<tr>
    <td style="border-left:1px solid #000; border-right:1px solid #000;">{{ row.hsn }}</td>
    <td style="border-left:1px solid #000; border-right:1px solid #000; text-align:right;">{{ "%.2f"|format(row.taxable) }}</td>
    <td style="border-left:1px solid #000; border-right:1px solid #000; text-align:center;">{{ "%.2f"|format(cgst_rate) }}%</td>
    <td style="border-left:1px solid #000; border-right:1px solid #000; text-align:right;">{{ "%.2f"|format(cgst_amt) }}</td>
    <td style="border-left:1px solid #000; border-right:1px solid #000; text-align:center;">{{ "%.2f"|format(sgst_rate) }}%</td>
    <td style="border-left:1px solid #000; border-right:1px solid #000; text-align:right;">{{ "%.2f"|format(sgst_amt) }}</td>
    <td style="border-left:1px solid #000; border-right:1px solid #000; text-align:right;">{{ "%.2f"|format(total) }}</td>
</tr>
{% set total_taxable.val = total_taxable.val + row.taxable %}
{% set total_tax.val     = total_tax.val + total %}
{% endfor %}
<!-- Total Row -->
<tr>
    <td style="border:1px solid #000; text-align:right;"><b>Total</b></td>
    <td style="border:1px solid #000; text-align:right;"><b>{{ "%.2f"|format(total_taxable.val) }}</b></td>
    <td style="border:1px solid #000;"></td>
    <td style="border:1px solid #000; text-align:right;"><b>{{ "%.2f"|format(total_taxable.val * (doc.taxes[0].rate if doc.taxes else 0) / 100 / 2) }}</b></td>
    <td style="border:1px solid #000;"></td>
    <td style="border:1px solid #000; text-align:right;"><b>{{ "%.2f"|format(total_taxable.val * (doc.taxes[0].rate if doc.taxes else 0) / 100 / 2) }}</b></td>
    <td style="border:1px solid #000; text-align:right;"><b>{{ "%.2f"|format(total_tax.val) }}</b></td>
</tr>
</tbody>
</table>

<!-- ===================== TAX AMOUNT IN WORDS ===================== -->
<table class="taxwords-table">
<tr>
